<?php
declare(strict_types=1);
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/research-knowledge.php';require_once __DIR__.'/app/research-intelligence.php';require_once __DIR__.'/app/research-workspace.php';
$u=require_user($pdo);$id=(string)($_GET['id']??$_POST['id']??'');$claim=research_claim_access($pdo,$u,$id);if(!$claim){http_response_code(404);exit('Research claim not found.');}$canWrite=project_can_write($claim);$success='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$op=(string)($_POST['op']??'');try{
    if(!$canWrite)throw new RuntimeException('You have view-only access to this project.');
    if($op==='update'){
        $status=(string)($_POST['status']??'unverified');if(!in_array($status,['unverified','supported','disputed','contradicted','resolved'],true))$status='unverified';
        $type=(string)($_POST['claim_type']??'factual');if(!in_array($type,['factual','disputed','prediction','interpretation','data_point'],true))$type='factual';
        $statement=trim((string)($_POST['statement']??''));if($statement==='')throw new RuntimeException('Claim statement is required.');
        $resolution=trim((string)($_POST['resolution_note']??''));
        $pdo->prepare('UPDATE research_claims SET statement=?,claim_type=?,status=?,resolution_note=? WHERE id=?')->execute([$statement,$type,$status,$resolution?:null,$claim['id']]);$success='Claim updated.';
    }
    if($op==='add_evidence'){
        $evidenceType=(string)($_POST['evidence_type']??'annotation');if(!in_array($evidenceType,['annotation','source_version'],true))throw new RuntimeException('Choose Annotation or Source evidence.');
        $relationship=(string)($_POST['relationship']??'supports');if(!in_array($relationship,['supports','contradicts','context','primary'],true))$relationship='supports';
        $ref=trim((string)($_POST['reference_id']??''));if($ref==='')throw new RuntimeException('Enter the Annotation or Source ID.');$annotationId=null;$versionId=0;
        if($evidenceType==='annotation'){$e=research_project_annotation_evidence($pdo,(int)$claim['project_id'],$ref);if(!$e)throw new RuntimeException('That annotation is not evidence in this Research project.');$annotationId=(int)$e['annotation_id'];$versionId=(int)$e['source_version_id'];}
        else{$e=research_project_source_evidence($pdo,(int)$claim['project_id'],$ref);if(!$e)throw new RuntimeException('That Source is not in this Research project or has no captured version yet.');$versionId=(int)$e['source_version_id'];}
        $pdo->prepare('INSERT INTO claim_evidence(public_id,claim_id,added_by_user_id,evidence_type,annotation_id,source_version_id,relationship,note) VALUES(?,?,?,?,?,?,?,?)')->execute([ulid_like(),$claim['id'],$u['id'],$evidenceType,$annotationId,$versionId,$relationship,trim((string)($_POST['note']??''))?:null]);$success='Evidence attached to the exact captured Source Version.';
    }
    if($op==='remove_evidence'){$evidence=(string)($_POST['evidence']??'');$pdo->prepare('DELETE FROM claim_evidence WHERE public_id=? AND claim_id=?')->execute([$evidence,$claim['id']]);$success='Evidence removed.';}
    if($success!==''&&function_exists('data_attribution_capture_object'))data_attribution_capture_object($pdo,(int)$u['id'],'claim',(string)$claim['public_id']);
    if($success!==''&&research_workspace_ready($pdo))research_workspace_queue($pdo,(int)$claim['project_id'],3);
}catch(Throwable $e){$error=$e->getMessage();}
$claim=research_claim_access($pdo,$u,$id)??$claim;}
$evidence=research_claim_evidence_rows($pdo,(int)$claim['id']);$relations=research_claim_relation_rows($pdo,(int)$claim['project_id'],(int)$claim['id']);$verification=research_verification_ready($pdo)?research_verification_claim_state($pdo,$u,$claim):null;
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Claim · Annotated</title><link rel="stylesheet" href="/assets/css/app.css"></head><body data-workspace-user="<?=h((string)$u['public_id'])?>" data-workspace-surface="research" data-workspace-research="<?=h((string)$claim['project_public_id'])?>" data-workspace-object-type="claim" data-workspace-object="<?=h((string)$claim['public_id'])?>"><header class="topbar"><a class="brand" href="/home.php">Annotated</a><nav><a href="/research-project.php?id=<?=h($claim['project_public_id'])?>">Project</a><a href="/research-graph.php?id=<?=h($claim['project_public_id'])?>">Claim Graph</a><a href="/research.php">Research</a></nav></header><main class="layout"><section><div class="pageTitle"><span class="eyebrow">CLAIM · <?=h(strtoupper($claim['claim_type']))?> · <?=h(strtoupper($claim['status']))?></span><h1><?=h($claim['statement'])?></h1><p>Evidence remains pinned to the Source Version captured when it was attached.</p><div class="inlineActions"><?php if($canWrite):?><a class="button secondary" href="/research-reviews.php?type=claim&subject=<?=h($claim['public_id'])?>">Request Review</a><?php endif?><a class="button secondary" href="/research-reviews.php">Review Center</a><a class="button secondary" href="/research-verification.php?id=<?=h($claim['project_public_id'])?>">Evidence Verification</a><a class="button secondary" href="/research-evidence-packs.php?id=<?=h($claim['project_public_id'])?>">Evidence Packs</a></div></div><?php if($success):?><div class="success"><?=h($success)?></div><?php endif?><?php if($error):?><div class="error"><?=h($error)?></div><?php endif?>
<?php if($verification):?><section class="card verificationClaimSummary"><div class="meta">PHASE 27 · EVIDENCE VERIFICATION</div><h2>Evidence state</h2><div class="verificationSignals"><div><span>Evidence</span><strong><?=h(ucwords(str_replace('_',' ',(string)$verification['evidence_state'])))?></strong></div><div><span>Corroboration</span><strong><?=h(ucwords(str_replace('_',' ',(string)$verification['corroboration'])))?></strong></div><div><span>Freshness</span><strong><?=h(ucwords(str_replace('_',' ',(string)$verification['freshness'])))?></strong></div><div><span>Human review</span><strong><?=h(ucwords(str_replace('_',' ',(string)$verification['human_review']['state'])))?></strong></div><div><span>Recorded integrity</span><strong><?=h(ucwords(str_replace('_',' ',(string)$verification['integrity'])))?></strong></div><div><span>Agent use</span><strong><?=h(ucwords(str_replace('_',' ',(string)$verification['agent_use'])))?></strong></div></div><p class="meta">These signals describe evidence and review state. They do not certify this Claim as true.</p></section><?php endif?>
<h2>Evidence</h2><?php if(!$evidence):?><div class="card empty">No evidence attached yet.</div><?php endif?><?php foreach($evidence as $e):?><article class="card"><div class="meta"><?=h(strtoupper($e['relationship']))?> · <?=h($e['evidence_type']==='annotation'?'Annotation evidence':'Source evidence')?> · Source Version <?=h((string)$e['version_number'])?> · <?=h($e['captured_at'])?></div><h3><a href="/source.php?id=<?=h($e['source_public_id'])?>"><?=h($e['source_title']?:$e['canonical_url'])?></a></h3><?php if($e['annotation_public_id']):?><p><a href="/annotation.php?id=<?=h($e['annotation_public_id'])?>">Open annotation</a></p><?php endif?><?php if($e['note']):?><p><?=nl2br(h($e['note']))?></p><?php endif?><?php if($canWrite):?><form method="post" class="inlineForm"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($claim['public_id'])?>"><input type="hidden" name="op" value="remove_evidence"><input type="hidden" name="evidence" value="<?=h($e['public_id'])?>"><button>Remove</button></form><?php endif?></article><?php endforeach?>
<h2>Related Claims</h2><?php if(!$relations):?><div class="card empty">No Claim Graph relationships yet. <a href="/research-graph.php?id=<?=h($claim['project_public_id'])?>">Open Claim Graph</a>.</div><?php endif?><?php foreach($relations as $r):?><?php $other=$r['direction']==='outgoing'?$r['target_public_id']:$r['source_public_id'];$otherStatement=$r['direction']==='outgoing'?$r['target_statement']:$r['source_statement'];?><article class="card"><div class="meta"><?=h(strtoupper($r['direction']))?> · <?=h(strtoupper(str_replace('_',' ',$r['relation_type'])))?></div><h3><a href="/research-claim.php?id=<?=h($other)?>"><?=h($otherStatement)?></a></h3><?php if($r['note']):?><p><?=nl2br(h($r['note']))?></p><?php endif?></article><?php endforeach?></section><aside><?php if($canWrite):?><div class="card"><h3>Edit claim</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($claim['public_id'])?>"><input type="hidden" name="op" value="update"><label>Statement<textarea name="statement" rows="5" required><?=h($claim['statement'])?></textarea></label><label>Type<select name="claim_type"><?php foreach(['factual','disputed','prediction','interpretation','data_point'] as $v):?><option value="<?=h($v)?>" <?=$claim['claim_type']===$v?'selected':''?>><?=h(ucwords(str_replace('_',' ',$v)))?></option><?php endforeach?></select></label><label>Status<select name="status"><?php foreach(['unverified','supported','disputed','contradicted','resolved'] as $v):?><option value="<?=h($v)?>" <?=$claim['status']===$v?'selected':''?>><?=h(ucfirst($v))?></option><?php endforeach?></select></label><label>Resolution note<textarea name="resolution_note" rows="3"><?=h($claim['resolution_note'])?></textarea></label><button>Save claim</button></form></div><div class="card"><h3>Attach evidence</h3><form method="post" class="stack"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><input type="hidden" name="id" value="<?=h($claim['public_id'])?>"><input type="hidden" name="op" value="add_evidence"><label>Evidence type<select name="evidence_type"><option value="annotation">Project annotation</option><option value="source_version">Project source</option></select></label><label>Annotation or Source ID<input name="reference_id" required placeholder="Paste Annotated ID"></label><label>Relationship<select name="relationship"><option value="supports">Supports</option><option value="contradicts">Contradicts</option><option value="context">Context</option><option value="primary">Primary</option></select></label><label>Note<textarea name="note" rows="3"></textarea></label><button>Attach evidence</button></form><p class="meta">Source evidence pins the Source's current captured version at the moment you attach it.</p></div><div class="card"><h3>Claim Graph</h3><p class="meta">Connect this Claim to other Claims in the project's graph.</p><p><a href="/research-graph.php?id=<?=h($claim['project_public_id'])?>">Open Claim Graph →</a></p></div><?php endif?></aside></main><script src="/assets/js/workspace-state.js?v=34.0"></script></body></html>
